export enum DeliverabilityBand {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

export interface EmailAccountData {
  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  warmupReputation: number | null;
  createdAt: string;
  updatedAt: string;
}

export class EmailAccountEntity {
  private readonly data: EmailAccountData;

  constructor(data: Partial<EmailAccountData> & { smartleadInboxId: string; smartleadClientId: string; email: string }) {
    const now = new Date().toISOString();
    this.data = {
      smartleadInboxId: data.smartleadInboxId,
      smartleadClientId: data.smartleadClientId,
      email: data.email,
      domain: data.domain ?? this.extractDomain(data.email),
      tags: data.tags ?? [],
      campaignIds: data.campaignIds ?? [],
      warmupReputation: data.warmupReputation ?? null,
      createdAt: data.createdAt ?? now,
      updatedAt: now,
    };
  }

  private extractDomain(email: string): string {
    const parts = email.split('@');
    return parts.length === 2 ? parts[1].toLowerCase() : '';
  }

  get smartleadInboxId(): string {
    return this.data.smartleadInboxId;
  }

  get smartleadClientId(): string {
    return this.data.smartleadClientId;
  }

  get email(): string {
    return this.data.email;
  }

  get domain(): string {
    return this.data.domain;
  }

  get tags(): string[] {
    return [...this.data.tags];
  }

  get campaignIds(): string[] {
    return [...this.data.campaignIds];
  }

  get numberOfCampaignAssociated(): number {
    return this.data.campaignIds.length;
  }

  get warmupReputation(): number | null {
    return this.data.warmupReputation;
  }

  get createdAt(): string {
    return this.data.createdAt;
  }

  get updatedAt(): string {
    return this.data.updatedAt;
  }

  get deliverabilityScore(): number | null {
    return this.data.warmupReputation;
  }

  get deliverabilityBand(): DeliverabilityBand {
    const score = this.data.warmupReputation;
    if (score === null || score === undefined) {
      return DeliverabilityBand.Unknown;
    }
    if (score === 100) {
      return DeliverabilityBand.High;
    }
    if (score >= 98) {
      return DeliverabilityBand.Medium;
    }
    if (score >= 95) {
      return DeliverabilityBand.Low;
    }
    return DeliverabilityBand.Burned;
  }

  addTag(tag: string): void {
    if (!this.data.tags.includes(tag)) {
      this.data.tags.push(tag);
      this.data.updatedAt = new Date().toISOString();
    }
  }

  removeTag(tag: string): void {
    const index = this.data.tags.indexOf(tag);
    if (index !== -1) {
      this.data.tags.splice(index, 1);
      this.data.updatedAt = new Date().toISOString();
    }
  }

  associateCampaign(campaignId: string): boolean {
    if (!this.data.campaignIds.includes(campaignId)) {
      this.data.campaignIds.push(campaignId);
      this.data.updatedAt = new Date().toISOString();
      return true;
    }
    return false;
  }

  dissociateCampaign(campaignId: string): boolean {
    const index = this.data.campaignIds.indexOf(campaignId);
    if (index !== -1) {
      this.data.campaignIds.splice(index, 1);
      this.data.updatedAt = new Date().toISOString();
      return true;
    }
    return false;
  }

  updateWarmupReputation(reputation: number): void {
    this.data.warmupReputation = reputation;
    this.data.updatedAt = new Date().toISOString();
  }

  updateFromSmartlead(data: { warmupReputation?: number; createdAt?: string }): void {
    if (data.warmupReputation !== undefined) {
      this.data.warmupReputation = data.warmupReputation;
    }
    if (data.createdAt) {
      this.data.createdAt = data.createdAt;
    }
    this.data.updatedAt = new Date().toISOString();
  }

  toJSON(): EmailAccountData {
    return { ...this.data };
  }

  static fromJSON(data: EmailAccountData): EmailAccountEntity {
    const entity = new EmailAccountEntity({
      smartleadInboxId: data.smartleadInboxId,
      smartleadClientId: data.smartleadClientId,
      email: data.email,
      domain: data.domain,
      tags: data.tags,
      campaignIds: data.campaignIds,
      warmupReputation: data.warmupReputation,
      createdAt: data.createdAt,
    });
    entity.data.updatedAt = data.updatedAt;
    return entity;
  }
}

