import { IsString, IsOptional, IsArray, IsNumber, Min, Max, ValidateNested, IsEnum } from 'class-validator';
import { Type } from 'class-transformer';
import { DeliverabilityBand } from '../entities/email-account.entity';

export class EmailAccountDto {
  @IsString()
  smartleadInboxId: string;

  @IsString()
  smartleadClientId: string;

  @IsString()
  email: string;

  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  tags?: string[];

  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  campaignIds?: string[];
}

export class EmailAccountListDto {
  @IsNumber()
  @Min(1)
  totalNumberOfEmailsToSend: number;

  @IsString()
  smartleadClientId: string;

  @IsString()
  campaignId: string;

  @IsOptional()
  @IsNumber()
  @Min(1)
  numberOfDaysInCampaign?: number;

  @IsOptional()
  @IsNumber()
  @Min(1)
  emailsPerInboxPerDay?: number;
}

export class AssociateCampaignDto {
  @IsArray()
  @IsString({ each: true })
  emailAccountIds: string[];

  @IsString()
  campaignId: string;
}

export class EmailAccountQueryDto {
  @IsOptional()
  @IsString()
  smartleadInboxId?: string;

  @IsOptional()
  @IsString()
  email?: string;

  @IsOptional()
  @IsString()
  smartleadClientId?: string;

  @IsOptional()
  @IsNumber()
  @Min(1)
  page?: number;

  @IsOptional()
  @IsNumber()
  @Min(1)
  @Max(100)
  pageSize?: number;
}

export class EmailAccountResponseDto {
  @IsString()
  smartleadInboxId: string;

  @IsString()
  smartleadClientId: string;

  @IsString()
  email: string;

  @IsString()
  domain: string;

  @IsArray()
  @IsString({ each: true })
  tags: string[];

  @IsArray()
  @IsString({ each: true })
  campaignIds: string[];

  @IsNumber()
  numberOfCampaignAssociated: number;

  @IsOptional()
  @IsNumber()
  warmupReputation: number | null;

  @IsEnum(DeliverabilityBand)
  deliverabilityBand: DeliverabilityBand;

  @IsString()
  createdAt: string;

  @IsString()
  updatedAt: string;
}

export class PaginatedEmailAccountsResponseDto {
  @ValidateNested({ each: true })
  @Type(() => EmailAccountResponseDto)
  data: EmailAccountResponseDto[];

  @IsNumber()
  total: number;

  @IsNumber()
  page: number;

  @IsNumber()
  pageSize: number;

  @IsNumber()
  totalPages: number;
}

export class SaveEmailAccountFromSmartleadDto {
  @IsString()
  smartleadInboxId: string;

  @IsString()
  smartleadClientId: string;
}

export class SyncReputationDto {
  @IsString()
  smartleadClientId: string;
}

