import { Injectable, Logger, NotFoundException, BadRequestException, InternalServerErrorException } from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { FindDataDto } from '../datastore/dto/find.dto';
import { documentType } from '../datastore/entites/documentType';
import { EmailAccountEntity, DeliverabilityBand, EmailAccountData } from './entities/email-account.entity';
import {
  EmailAccountDto,
  EmailAccountListDto,
  AssociateCampaignDto,
  EmailAccountQueryDto,
  EmailAccountResponseDto,
  PaginatedEmailAccountsResponseDto,
  SaveEmailAccountFromSmartleadDto,
  SyncReputationDto,
} from './dto/emailAccount.dto';

const DEFAULT_DAYS_IN_CAMPAIGN = 10;
const DEFAULT_EMAILS_PER_INBOX_PER_DAY = 20;
const SMARTLEAD_API_BASE = 'https://server.smartlead.ai/api/v1';

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);

  constructor(private readonly datastoreService: DatastoreService) {}

  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign,
    totalNumberOfEmailsToSend,
    emailsPerInboxPerDay,
  }: EmailAccountListDto): Promise<EmailAccountResponseDto[]> {
    this.logger.log(`Getting best email accounts for campaign ${campaignId} for client ${smartleadClientId}`);

    const days = numberOfDaysInCampaign ?? DEFAULT_DAYS_IN_CAMPAIGN;
    const emailsPerDay = emailsPerInboxPerDay ?? DEFAULT_EMAILS_PER_INBOX_PER_DAY;

    const requiredPool = Math.floor(totalNumberOfEmailsToSend / days / emailsPerDay);
    this.logger.log(`Required pool size: ${requiredPool} (total: ${totalNumberOfEmailsToSend}, days: ${days}, emails/day: ${emailsPerDay})`);

    if (requiredPool <= 0) {
      return [];
    }

    const allAccounts = await this.getEmailAccountsByClientId(smartleadClientId);

    if (allAccounts.length === 0) {
      this.logger.warn(`No email accounts found for client ${smartleadClientId}`);
      return [];
    }

    const rankedAccounts = this.rankAccountsForCampaign(allAccounts, smartleadClientId);

    const selectedAccounts = rankedAccounts.slice(0, requiredPool);

    this.logger.log(`Selected ${selectedAccounts.length} email accounts for campaign ${campaignId}`);

    return selectedAccounts.map(this.toResponseDto);
  }

  private rankAccountsForCampaign(accounts: EmailAccountEntity[], clientId: string): EmailAccountEntity[] {
    const accountsWithSameDomainCount = accounts.map(account => ({
      account,
      sameDomainCount: accounts.filter(a => a.domain === account.domain && a.smartleadInboxId !== account.smartleadInboxId).length,
    }));

    return accountsWithSameDomainCount
      .sort((a, b) => {
        const scoreA = a.account.deliverabilityScore ?? -1;
        const scoreB = b.account.deliverabilityScore ?? -1;

        if (scoreB !== scoreA) {
          return scoreB - scoreA;
        }

        const campaignsA = a.account.numberOfCampaignAssociated;
        const campaignsB = b.account.numberOfCampaignAssociated;
        if (campaignsA !== campaignsB) {
          return campaignsA - campaignsB;
        }

        if (a.sameDomainCount !== b.sameDomainCount) {
          return a.sameDomainCount - b.sameDomainCount;
        }

        return new Date(a.account.createdAt).getTime() - new Date(b.account.createdAt).getTime();
      })
      .map(item => item.account);
  }

  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateCampaignDto): Promise<{ associated: string[]; skipped: string[] }> {
    this.logger.log(`Associating ${emailAccountIds.length} email accounts with campaign ${campaignId}`);

    const uniqueIds = [...new Set(emailAccountIds)];

    if (uniqueIds.length !== emailAccountIds.length) {
      this.logger.log(`Duplicate inbox IDs in request, treating as single: ${emailAccountIds.length} -> ${uniqueIds.length}`);
    }

    const accounts = await Promise.all(
      uniqueIds.map(id => this.getEmailAccountByIdInternal(id))
    );

    const missingIds = uniqueIds.filter((id, index) => !accounts[index]);
    if (missingIds.length > 0) {
      this.logger.error(`Email accounts not found: ${missingIds.join(', ')}`);
      throw new NotFoundException(`Email accounts not found: ${missingIds.join(', ')}`);
    }

    const associated: string[] = [];
    const skipped: string[] = [];

    for (const account of accounts) {
      if (account!.associateCampaign(campaignId)) {
        await this.saveEmailAccountInternal(account!);
        associated.push(account!.smartleadInboxId);
      } else {
        skipped.push(account!.smartleadInboxId);
      }
    }

    this.logger.log(`Associated ${associated.length} accounts, skipped ${skipped.length} (already associated)`);

    return { associated, skipped };
  }

  async saveEmailAccount(emailAccount: EmailAccountDto): Promise<EmailAccountResponseDto> {
    this.logger.log(`Saving email account ${emailAccount.smartleadInboxId}`);

    const entity = new EmailAccountEntity({
      smartleadInboxId: emailAccount.smartleadInboxId,
      smartleadClientId: emailAccount.smartleadClientId,
      email: emailAccount.email,
      tags: emailAccount.tags,
      campaignIds: emailAccount.campaignIds,
    });

    return this.saveEmailAccountInternal(entity);
  }

  private async saveEmailAccountInternal(entity: EmailAccountEntity): Promise<EmailAccountResponseDto> {
    const storeDataDto = new StoreDataDto({
      data: entity.toJSON(),
      context: { documentType: documentType.EMAIL_ACCOUNT },
    });

    await this.datastoreService.store(storeDataDto);

    this.logger.log(`Saved email account ${entity.smartleadInboxId}`);
    return this.toResponseDto(entity);
  }

  async getEmailAccount(query: EmailAccountDto): Promise<EmailAccountResponseDto | null> {
    if (query.smartleadInboxId) {
      return this.getEmailAccountById(query.smartleadInboxId);
    }
    if (query.email) {
      return this.getEmailAccountByEmail(query.email);
    }
    if (query.smartleadClientId) {
      const accounts = await this.getEmailAccountsByClientId(query.smartleadClientId);
      return accounts.length > 0 ? this.toResponseDto(accounts[0]) : null;
    }
    return null;
  }

  async getEmailAccountById(smartleadInboxId: string): Promise<EmailAccountResponseDto | null> {
    const entity = await this.getEmailAccountByIdInternal(smartleadInboxId);
    return entity ? this.toResponseDto(entity) : null;
  }

  private async getEmailAccountByIdInternal(smartleadInboxId: string): Promise<EmailAccountEntity | null> {
    const result = await this.datastoreService.getById({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data) {
      return null;
    }

    return EmailAccountEntity.fromJSON(result.data as EmailAccountData);
  }

  async getEmailAccountByEmail(email: string): Promise<EmailAccountResponseDto | null> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'email',
      fieldValue: email,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data || result.data.length === 0) {
      return null;
    }

    return this.toResponseDto(EmailAccountEntity.fromJSON(result.data[0] as EmailAccountData));
  }

  async getEmailAccountsByClientId(smartleadClientId: string): Promise<EmailAccountEntity[]> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'smartleadClientId',
      fieldValue: smartleadClientId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data || result.data.length === 0) {
      return [];
    }

    return (result.data as EmailAccountData[]).map(data => EmailAccountEntity.fromJSON(data));
  }

  async getAllEmailAccounts(query: EmailAccountQueryDto): Promise<PaginatedEmailAccountsResponseDto> {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 20;

    let result;
    if (query.smartleadClientId) {
      result = await this.datastoreService.getByField({
        fieldKey: 'smartleadClientId',
        fieldValue: query.smartleadClientId,
        documentType: documentType.EMAIL_ACCOUNT,
        pagination: { page, pageSize },
      });
    } else {
      result = await this.datastoreService.getByPattern({
        pattern: '*',
        documentType: documentType.EMAIL_ACCOUNT,
      });
    }

    let accounts: EmailAccountEntity[] = [];
    let total = 0;

    if (result?.data) {
      if (Array.isArray(result.data)) {
        accounts = (result.data as EmailAccountData[]).map(data => EmailAccountEntity.fromJSON(data));
        total = accounts.length;
      } else if (result.data.data && Array.isArray(result.data.data)) {
        accounts = (result.data.data as EmailAccountData[]).map(data => EmailAccountEntity.fromJSON(data));
        total = result.data.total ?? accounts.length;
      }
    }

    if (query.email) {
      accounts = accounts.filter(a => a.email.toLowerCase() === query.email!.toLowerCase());
      total = accounts.length;
    }
    if (query.smartleadInboxId) {
      accounts = accounts.filter(a => a.smartleadInboxId === query.smartleadInboxId);
      total = accounts.length;
    }

    const start = (page - 1) * pageSize;
    const paginatedAccounts = accounts.slice(start, start + pageSize);

    return {
      data: paginatedAccounts.map(this.toResponseDto),
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async deleteEmailAccount(smartleadInboxId: string): Promise<void> {
    this.logger.log(`Deleting email account ${smartleadInboxId}`);

    const entity = await this.getEmailAccountByIdInternal(smartleadInboxId);
    if (!entity) {
      throw new NotFoundException(`Email account ${smartleadInboxId} not found`);
    }

    await this.datastoreService.remove({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    this.logger.log(`Deleted email account ${smartleadInboxId}`);
  }

  async saveEmailAccountFromSmartlead(dto: SaveEmailAccountFromSmartleadDto): Promise<EmailAccountResponseDto> {
    this.logger.log(`Saving email account from Smartlead: ${dto.smartleadInboxId} for client ${dto.smartleadClientId}`);

    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    if (!apiKey) {
      throw new InternalServerErrorException('Smartlead API key not configured');
    }

    const url = `${SMARTLEAD_API_BASE}/email-accounts/${dto.smartleadInboxId}?api_key=${apiKey}`;

    try {
      const response = await fetch(url);

      if (response.status === 404) {
        throw new NotFoundException(`Smartlead inbox ${dto.smartleadInboxId} not found`);
      }

      if (!response.ok) {
        throw new InternalServerErrorException(`Failed to fetch email account from Smartlead: ${response.status}`);
      }

      const data = await response.json();

      if (data.client_id && data.client_id.toString() !== dto.smartleadClientId) {
        this.logger.warn(`Inbox ${dto.smartleadInboxId} belongs to client ${data.client_id}, not ${dto.smartleadClientId}`);
      }

      const entity = new EmailAccountEntity({
        smartleadInboxId: dto.smartleadInboxId,
        smartleadClientId: dto.smartleadClientId,
        email: data.email_address,
        warmupReputation: data.warmup_reputation_score ?? data.reputation_score ?? null,
        createdAt: data.created_at,
      });

      return this.saveEmailAccountInternal(entity);
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error(`Error fetching email account from Smartlead: ${error}`);
      throw new InternalServerErrorException(`Failed to fetch email account from Smartlead: ${error.message}`);
    }
  }

  async syncReputation(dto: SyncReputationDto): Promise<{ updated: number; errors: string[] }> {
    this.logger.log(`Syncing reputation for client ${dto.smartleadClientId}`);

    const accounts = await this.getEmailAccountsByClientId(dto.smartleadClientId);
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;

    if (!apiKey) {
      throw new InternalServerErrorException('Smartlead API key not configured');
    }

    let updated = 0;
    const errors: string[] = [];

    for (const account of accounts) {
      try {
        const url = `${SMARTLEAD_API_BASE}/email-accounts/${account.smartleadInboxId}?api_key=${apiKey}`;
        const response = await fetch(url);

        if (!response.ok) {
          errors.push(`Failed to fetch ${account.smartleadInboxId}: ${response.status}`);
          continue;
        }

        const data = await response.json();
        const reputation = data.warmup_reputation_score ?? data.reputation_score ?? null;

        if (reputation !== null && reputation !== account.warmupReputation) {
          account.updateWarmupReputation(reputation);
          await this.saveEmailAccountInternal(account);
          updated++;
        }
      } catch (error) {
        errors.push(`Error syncing ${account.smartleadInboxId}: ${error.message}`);
      }
    }

    this.logger.log(`Reputation sync complete: ${updated} updated, ${errors.length} errors`);
