import {
  Controller,
  Get,
  Post,
  Delete,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import {
  EmailAccountDto,
  EmailAccountListDto,
  AssociateCampaignDto,
  EmailAccountQueryDto,
  SaveEmailAccountFromSmartleadDto,
  SyncReputationDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @Post('accounts')
  @HttpCode(HttpStatus.CREATED)
  async createEmailAccount(@Body() dto: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(dto);
  }

  @Post('accounts/from-smartlead')
  @HttpCode(HttpStatus.CREATED)
  async createEmailAccountFromSmartlead(@Body() dto: SaveEmailAccountFromSmartleadDto) {
    return this.emailinfraService.saveEmailAccountFromSmartlead(dto);
  }

  @Get('accounts')
  async getEmailAccounts(@Query() query: EmailAccountQueryDto) {
    return this.emailinfraService.getAllEmailAccounts(query);
  }

  @Get('accounts/:smartleadInboxId')
  async getEmailAccountById(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccountById(smartleadInboxId);
  }

  @Get('accounts/email/:email')
  async getEmailAccountByEmail(@Param('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @Get('accounts/client/:smartleadClientId')
  async getEmailAccountsByClient(@Param('smartleadClientId') smartleadClientId: string) {
    return this.emailinfraService.getEmailAccountsByClientId(smartleadClientId);
  }

  @Delete('accounts/:smartleadInboxId')
  @HttpCode(HttpStatus.NO_CONTENT)
  async deleteEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }

  @Post('accounts/associate-campaign')
  @HttpCode(HttpStatus.OK)
  async associateEmailAccountsWithCampaign(@Body() dto: AssociateCampaignDto) {
    return this.emailinfraService.associateEmailAccountsWithCampaign(dto);
  }

  @Post('campaigns/best-accounts')
  async getBestEmailAccountsForCampaign(@Body() dto: EmailAccountListDto) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(dto);
  }

  @Post('accounts/sync-reputation')
  @HttpCode(HttpStatus.OK)
  async syncReputation(@Body() dto: SyncReputationDto) {
    return this.emailinfraService.syncReputation(dto);
  }
}

